const msg2 = productionOrderEventMessages.length > 0 ? productionOrderEventMessages : null;

node.status({
    fill: "green",
    shape: "dot",
    text: `slot: ${slotEventMessages.length}, order: ${productionOrderEventMessages.length}`
});

return [msg1, msg2];

